function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

function decimalsFromStep(step) {
      const s = String(step);
      return s.includes('.') ? s.split('.')[1].length : 0;
    }

function roundToStep(value, step) {
      if (!step) return value;
      const rounded = Math.round(value / step) * step;
      return Number(rounded.toFixed(decimalsFromStep(step)));
    }

function isParamDisabled(block, param) {
      if (!block || !param) return false;

      const name = normaliseName(param.name);

      if (name.includes('sync note')) {
        const sync = relatedSyncParam(block.params, param.name);
        return sync ? isSyncOff(sync) : false;
      }

      if (name === 'delay time' || name === 'delay time l' || name === 'delay time r' ||
          name === 'rate' || name === 'speed') {
        const sync = relatedSyncParam(block.params, param.name);
        return sync ? !isSyncOff(sync) : false;
      }

      return false;
    }

function relatedSyncParam(params, paramName) {
      const n = normaliseName(paramName);

      if (n.includes(' l')) {
        return params.find(p => normaliseName(p.name) === 'sync l') || params.find(p => normaliseName(p.name) === 'sync');
      }

      if (n.includes(' r')) {
        return params.find(p => normaliseName(p.name) === 'sync r') || params.find(p => normaliseName(p.name) === 'sync');
      }

      return params.find(p => normaliseName(p.name) === 'sync');
    }

function isSyncOff(syncParam) {
      if (!syncParam || !syncParam.meta || syncParam.meta.kind !== 'enum') return true;

      const label = String(syncParam.meta.options[syncParam.value] || '').toLowerCase();
      return label === 'off';
    }

