const AMP_WRITE_IDS = {
      gain: 0x00,
      level: 0x01,
      bass: 0x02,
      mid: 0x03,
      treble: 0x04
    };

async function setAmpKnob(key, rawValue) {
      const id = AMP_WRITE_IDS[key];

      if (id === undefined) {
        log('Amp ' + key + ' set to raw=' + rawValue + ' (write not yet confirmed -- not sent to device)');
        return;
      }

      const valueBytes = encodeVarint(clamp(Math.round(rawValue), 0, 255));
      const payload = new Uint8Array([0x00, 0xC0, 0x18, id, 0x20, ...valueBytes, 0x28, 0x00, 0x1A, 0x00, 0x00, 0x00]);
      payload[0] = payload.length - 2;

      await writeC304('Amp ' + key + ' = ' + rawValue, payload, 'amp:' + key);
    }

