state.mc6 = { selected: [1, 2, 3, 4, 5], channel: 1, bankName: 'Nano Cortex', mixSlot: -1, records: {}, busy: false };

function waitForPresetState(preset, timeoutMs) {
      return new Promise(resolve => {
        const done = ok => { clearTimeout(timer); presetStateWaiters.splice(presetStateWaiters.indexOf(waiter), 1); resolve(ok); };
        const waiter = () => { if (state.selectedPreset === preset) done(true); };
        const timer = setTimeout(() => done(false), timeoutMs);
        presetStateWaiters.push(waiter);
      });
    }

function renderMc6Panel() {
      const ch = $('mc6Channel');
      if (!ch.options.length) ch.innerHTML = Array.from({ length: 16 }, (_, i) => '<option value="' + (i + 1) + '">' + (i + 1) + '</option>').join('');
      ch.value = String(state.mc6.channel);
      $('mc6BankName').value = state.mc6.bankName;
      $('mc6MixSlot').value = String(state.mc6.mixSlot);
      const sel = state.mc6.selected.slice().sort((a, b) => a - b);
      $('mc6Count').textContent = sel.length + ' of 5 presets selected (A–E in preset order)';
      const list = $('mc6Presets');
      list.innerHTML = '';
      for (let i = 1; i <= 64; i++) {
        const idx = sel.indexOf(i);
        const row = document.createElement('label');
        row.className = 'mc6-preset' + (idx >= 0 ? ' on' : '') + (idx < 0 && sel.length >= 5 ? ' disabled' : '');
        row.innerHTML = '<input type="checkbox"' + (idx >= 0 ? ' checked' : '') + (idx < 0 && sel.length >= 5 ? ' disabled' : '') + '>' +
          '<span class="n">' + i + '</span><span class="name">' + escapeHTML(state.presetNames.get(i) || 'Preset ' + i) + '</span>' +
          (idx >= 0 ? '<span class="mc6-letter">' + 'ABCDE'[idx] + '</span>' : '');
        row.querySelector('input').addEventListener('change', e => {
          if (e.target.checked) { if (state.mc6.selected.length < 5) state.mc6.selected.push(i); }
          else state.mc6.selected = state.mc6.selected.filter(x => x !== i);
          renderMc6Panel();
        });
        list.appendChild(row);
      }
    }

